// Generated by patch/make_airdrop_unlocks.py: the level that unlocks each
// airdrop that starts locked (by ItemID). The server grants them.
var AirdropUnlockLevels = {"140111": 8, "140112": 6, "140115": 6, "140126": 10, "140138": 9, "140142": 6};

rivets.formatters.airdropUnlockText = function (itemID) {
  var level = AirdropUnlockLevels[String(itemID)];
  return level ? "LVL " + level : "";
};

rivets.formatters.airdropUnlockNote = function (itemID) {
  var level = AirdropUnlockLevels[String(itemID)];
  return level ? "Unlocks at level " + level : "";
};
